(4651182, 671289, 92383, '<td valign="top">looks like a fly eye, which would be really funny :)</td>', 'looks like a fly eye, which would be really funny :)', '2008-04-21 09:25:42.000000', NULL, 1),
(4651185, 670707, 79955, '<td valign="top">Need better lighting to get the details &amp; colors from the fish. the dark background also blends too much with the fish</td>', 'Need better lighting to get the details & colors from the fish. the dark background also blends too much with the fish', '2008-04-21 09:27:06.000000', NULL, 1),
(4651187, 671321, 79955, '<td valign="top">I love this , wonderful subject, nice saturated colors. Really cool shot 8</td>', 'I love this , wonderful subject, nice saturated colors. Really cool shot 8', '2008-04-21 09:27:50.000000', NULL, 1),
(4651189, 671203, 30861, '<td valign="top">"Such a fine anise you are..."</td>', '"Such a fine anise you are..."', '2008-04-21 09:28:51.000000', NULL, 1),
(4651194, 669646, 30861, '<td valign="top">This has a LOT going for it. The processing (looks like tone mapping) is really nice for this scene. Unfortunately, the whole thing lacks that sense of critical sharpness that would elevate it another rung, and the BG to the upper left is bleeding off and robbing a little power from the image. If you''d done a vignette from the top corners to tone them down, the frog would pop a little better I think. Still, nice shot :-)</td>', 'This has a LOT going for it. The processing (looks like tone mapping) is really nice for this scene. Unfortunately, the whole thing lacks that sense of critical sharpness that would elevate it another rung, and the BG to the upper left is bleeding off and robbing a little power from the image. If you''d done a vignette from the top corners to tone them down, the frog would pop a little better I think. Still, nice shot :-)', '2008-04-21 09:33:50.000000', NULL, 1),
(4651196, 671434, 51269, '<td valign="top">Delightful !</td>', 'Delightful !', '2008-04-21 09:34:57.000000', NULL, 1),
