(4651554, 670998, 7033, '<td valign="top">I really like the subdued tone.  Nicely done!</td>', 'I really like the subdued tone.  Nicely done!', '2008-04-21 12:42:42.000000', NULL, 1),
(4651557, 671457, 7033, '<td valign="top">I love this perspective, and the colors are perfect.  Hands are a bit distracting for me, though. - 7</td>', 'I love this perspective, and the colors are perfect.  Hands are a bit distracting for me, though. - 7', '2008-04-21 12:44:03.000000', NULL, 1),
(4651559, 671168, 7033, '<td valign="top">Mmmmm... That said, I love the rich colors and stark contrast with the background.  There is one little speck to the left of the chocolate stream near the top of the frame that keeps drawing my eye away, though.  - 9</td>', 'Mmmmm... That said, I love the rich colors and stark contrast with the background.  There is one little speck to the left of the chocolate stream near the top of the frame that keeps drawing my eye away, though.  - 9', '2008-04-21 12:46:19.000000', NULL, 1),
(4651564, 670973, 7033, '<td valign="top">Beautiful!  Rich color, nice subdued tones.  One of my favorites of the challenge. -10</td>', 'Beautiful!  Rich color, nice subdued tones.  One of my favorites of the challenge. -10', '2008-04-21 12:48:53.000000', NULL, 1),
(4651569, 671211, 7033, '<td valign="top">I really like the sharp contrast of the edge of the water droplet against the backdrop of the strands of the feather.  Composition seems just a bit out of balance to me, though - not quite centered, not quite thirds.  -8</td>', 'I really like the sharp contrast of the edge of the water droplet against the backdrop of the strands of the feather.  Composition seems just a bit out of balance to me, though - not quite centered, not quite thirds.  -8', '2008-04-21 12:50:39.000000', NULL, 1),
(4651575, 670907, 7033, '<td valign="top">Beautiful tones - the burgundy backdrop adds a great deal to the mood of the shot.</td>', 'Beautiful tones - the burgundy backdrop adds a great deal to the mood of the shot.', '2008-04-21 12:52:13.000000', NULL, 1),
(4651589, 671476, 83328, '<td valign="top">nice title, i like the use of the vignette</td>', 'nice title, i like the use of the vignette', '2008-04-21 13:06:27.000000', NULL, 1),
