(4655670, 669646, 74273, '<td valign="top">great capture. the color is really vivid and I like the composition</td>', 'great capture. the color is really vivid and I like the composition', '2008-04-23 14:16:19.000000', NULL, 1),
(4655676, 670973, 74273, '<td valign="top">amazing detail. I really could see this as a large framed photo in someone''s kitchen. nice colors</td>', 'amazing detail. I really could see this as a large framed photo in someone''s kitchen. nice colors', '2008-04-23 14:17:55.000000', NULL, 1),
(4655683, 671148, 74273, '<td valign="top">I love the little bit of snow on his head. great capture.</td>', 'I love the little bit of snow on his head. great capture.', '2008-04-23 14:19:32.000000', NULL, 1),
(4655694, 670715, 74273, '<td valign="top">I love the black and white diagonal shadow in the background...that really makes the shot.</td>', 'I love the black and white diagonal shadow in the background...that really makes the shot.', '2008-04-23 14:24:01.000000', NULL, 1),
(4655701, 671287, 83313, '<td valign="top">Nice perspective, and I like the texture. My eye sees to be drawn up to the top area that is out of focus, however. A Deep DOF is always hard to achieve at such close range.</td>', 'Nice perspective, and I like the texture. My eye sees to be drawn up to the top area that is out of focus, however. A Deep DOF is always hard to achieve at such close range.', '2008-04-23 14:25:25.000000', NULL, 1),
(4655703, 671031, 74273, '<td valign="top">I love this shot. I love the low lighting and the color. I wish a little more of the shell had been in focus, but still, great shot.</td>', 'I love this shot. I love the low lighting and the color. I wish a little more of the shell had been in focus, but still, great shot.', '2008-04-23 14:26:25.000000', NULL, 1),
(4655705, 671299, 83313, '<td valign="top">Nice. Not a bug, I''m sure it enjoys a nice juicy one. One of the better lizard shots I''ve seen of late. Hope you put some notes in with this saying what kind of lizard this is.</td>', 'Nice. Not a bug, I''m sure it enjoys a nice juicy one. One of the better lizard shots I''ve seen of late. Hope you put some notes in with this saying what kind of lizard this is.', '2008-04-23 14:27:38.000000', NULL, 1),
(4655709, 670713, 83313, '<td valign="top">Nice colors and mood. It would have worked except for an excessive amount of JPEG artifacts showing. They are most noticeable around the edges of the flame and just inside the tip of it. Your file size of 101k is reasonable for the image, so I think at some time during working on this, you saved it with an excessive amount of compression. A good workflow is to save your file in either a TIFF or your image editors native format, until you are ready to post the final product. That way you don''t lose any detail.</td>', 'Nice colors and mood. It would have worked except for an excessive amount of JPEG artifacts showing. They are most noticeable around the edges of the flame and just inside the tip of it. Your file size of 101k is reasonable for the image, so I think at some time during working on this, you saved it with an excessive amount of compression. A good workflow is to save your file in either a TIFF or your image editors native format, until you are ready to post the final product. That way you don''t lose any detail.', '2008-04-23 14:33:20.000000', NULL, 1),
(4655713, 670910, 83313, '<td valign="top">Nice, though there is a minor loss of DOF toward the edges. Perhaps pulling back a touch in order to get greater DOF and cropping it closer could help, but I don''t really know what you were working with.</td>', 'Nice, though there is a minor loss of DOF toward the edges. Perhaps pulling back a touch in order to get greater DOF and cropping it closer could help, but I don''t really know what you were working with.', '2008-04-23 14:35:33.000000', NULL, 1),
(4655716, 671345, 83313, '<td valign="top">Cool looking. What are the colorful flashes of light from?</td>', 'Cool looking. What are the colorful flashes of light from?', '2008-04-23 14:36:32.000000', NULL, 1),
(4655719, 671018, 83313, '<td valign="top">Excellent lighting and sharpness. This has some nice dimension to it.</td>', 'Excellent lighting and sharpness. This has some nice dimension to it.', '2008-04-23 14:37:17.000000', NULL, 1),
(4655722, 671117, 83313, '<td valign="top">Lots of nice texture here. Not sure about the b/w, but I would have to see the color version to know for sure.</td>', 'Lots of nice texture here. Not sure about the b/w, but I would have to see the color version to know for sure.', '2008-04-23 14:38:40.000000', NULL, 1),
(4655727, 671203, 83313, '<td valign="top">Looks like a still life using existing lighting coming in from a window. Finding the right light is everything for some shots. Nice job on this.</td>', 'Looks like a still life using existing lighting coming in from a window. Finding the right light is everything for some shots. Nice job on this.', '2008-04-23 14:40:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4655731, 671403, 83313, '<td valign="top">Cropped a bit to much off the muffin top. It''s a decent shot, but not giving me that impression of deliciousness that makes me want one. Not sure exactly what it is, though.</td>', 'Cropped a bit to much off the muffin top. It''s a decent shot, but not giving me that impression of deliciousness that makes me want one. Not sure exactly what it is, though.', '2008-04-23 14:42:35.000000', NULL, 1),
(4655733, 671438, 83313, '<td valign="top">An interesting and detailed shot of a common item.</td>', 'An interesting and detailed shot of a common item.', '2008-04-23 14:43:06.000000', NULL, 1),
(4655734, 671365, 83313, '<td valign="top">Nice lighting and colors, perfect DOF for the subject, good comp. Great all around.</td>', 'Nice lighting and colors, perfect DOF for the subject, good comp. Great all around.', '2008-04-23 14:44:08.000000', NULL, 1),
(4655738, 671167, 83313, '<td valign="top">Staring me down will not get you a higher vote! Excellent details showing.</td>', 'Staring me down will not get you a higher vote! Excellent details showing.', '2008-04-23 14:45:12.000000', NULL, 1),
(4655743, 671477, 83313, '<td valign="top">This should be a shot that makes me go "Ooooh!" but it''s just a little shy of it. Just needs a little more of something that I can''t put my finger on.</td>', 'This should be a shot that makes me go "Ooooh!" but it''s just a little shy of it. Just needs a little more of something that I can''t put my finger on.', '2008-04-23 14:47:44.000000', NULL, 1),
(4655744, 671111, 83313, '<td valign="top">Simple and bold. I like it.</td>', 'Simple and bold. I like it.', '2008-04-23 14:48:07.000000', NULL, 1),
(4655749, 670786, 66602, '<td valign="top">lacks visual interest in my opinion, nothing macro about it</td>', 'lacks visual interest in my opinion, nothing macro about it', '2008-04-23 14:50:35.000000', NULL, 1),
(4655754, 671309, 83313, '<td valign="top">Can''t quite figure out what it is, though the title has me guessing. My coworker says it looked like a stack of pizzas from over at his desk. A bit of noise showing in the grey background. It''s not excessive, but the advanced rules could have allowed you to smooth it out without killing the detail in the main subject.</td>', 'Can''t quite figure out what it is, though the title has me guessing. My coworker says it looked like a stack of pizzas from over at his desk. A bit of noise showing in the grey background. It''s not excessive, but the advanced rules could have allowed you to smooth it out without killing the detail in the main subject.', '2008-04-23 14:51:58.000000', NULL, 1),
