(4659674, 669763, 10047, '<td valign="top">I think if you had moved this outside to take the shot the lighting would have been better.</td>', 'I think if you had moved this outside to take the shot the lighting would have been better.', '2008-04-25 20:57:37.000000', NULL, 1),
