INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4659846, 671462, 25773, '<td valign="top">Great details and colors. The background with the bright colors is a bit distracting.</td>', 'Great details and colors. The background with the bright colors is a bit distracting.', '2008-04-26 00:24:31.000000', NULL, 1),
(4659851, 669646, 25773, '<td valign="top">Colors and composition/situation are great. I feel, on this page, a little more sharpness would make it perfect.</td>', 'Colors and composition/situation are great. I feel, on this page, a little more sharpness would make it perfect.', '2008-04-26 00:27:41.000000', NULL, 1),
(4659856, 670236, 90947, '<td valign="top">Just a thought.  Perhaps bringing the focus point a little closer... perhaps at 10cm.</td>', 'Just a thought.  Perhaps bringing the focus point a little closer... perhaps at 10cm.', '2008-04-26 00:30:46.000000', NULL, 1),
(4659864, 671202, 90947, '<td valign="top">Great shot.  Interesting colors and textures.  I wonder what this is? something viscous like high fructose corn syrup?</td>', 'Great shot.  Interesting colors and textures.  I wonder what this is? something viscous like high fructose corn syrup?', '2008-04-26 00:32:42.000000', NULL, 1),
(4659865, 671456, 90947, '<td valign="top">I think you might have added a reflector to soften the shadow on the right side of the screw.</td>', 'I think you might have added a reflector to soften the shadow on the right side of the screw.', '2008-04-26 00:33:46.000000', NULL, 1),
(4659871, 670712, 25773, '<td valign="top">I have tried this once and it didn''t work, neither does here (for me). Somehow you would need a second-pointer emitting light or brighter than the other pointers. This way at each position it gets 1/10 of the light as the rest of the picture and becomes barely recognizable(maybe if you make it an HDR...). Otherwise superior clarity, details and perfect lighting (which is why is still 7 from me).</td>', 'I have tried this once and it didn''t work, neither does here (for me). Somehow you would need a second-pointer emitting light or brighter than the other pointers. This way at each position it gets 1/10 of the light as the rest of the picture and becomes barely recognizable(maybe if you make it an HDR...). Otherwise superior clarity, details and perfect lighting (which is why is still 7 from me).', '2008-04-26 00:37:43.000000', NULL, 1),
(4659875, 670682, 25773, '<td valign="top">A winner on my list...</td>', 'A winner on my list...', '2008-04-26 00:41:16.000000', NULL, 1),
(4659886, 671468, 90947, '<td valign="top">and a very new set of leaves.</td>', 'and a very new set of leaves.', '2008-04-26 00:49:32.000000', NULL, 1),
(4659888, 671443, 90947, '<td valign="top">I don''t see anything in sharp focus.  Love the clarinet... looks like mine.</td>', 'I don''t see anything in sharp focus.  Love the clarinet... looks like mine.', '2008-04-26 00:50:41.000000', NULL, 1),
(4659889, 671277, 90947, '<td valign="top">oh my... you are coming awfully close to a flower.  Nice crisp focus on the seeds in the foreground.</td>', 'oh my... you are coming awfully close to a flower.  Nice crisp focus on the seeds in the foreground.', '2008-04-26 00:52:51.000000', NULL, 1),
(4659890, 671207, 25773, '<td valign="top">Wow, looks challenging...and great.</td>', 'Wow, looks challenging...and great.', '2008-04-26 00:53:06.000000', NULL, 1),
(4659894, 671426, 90947, '<td valign="top">What great lighting.  great focus.</td>', 'What great lighting.  great focus.', '2008-04-26 00:56:58.000000', NULL, 1),
(4659901, 670098, 77683, '<td valign="top">the composition is kinda awkward, maybe if was centered, with more space between the end and the frame edge</td>', 'the composition is kinda awkward, maybe if was centered, with more space between the end and the frame edge', '2008-04-26 01:03:24.000000', NULL, 1),
(4659918, 671148, 40484, '<td valign="top">Nice close up on the bird. The post processing could use more work, imho. There are spots on the head that appear oversaturated to me.</td>', 'Nice close up on the bird. The post processing could use more work, imho. There are spots on the head that appear oversaturated to me.', '2008-04-26 01:15:40.000000', NULL, 1),
(4659999, 671321, 61396, '<td valign="top">I can almost see a fish</td>', 'I can almost see a fish', '2008-04-26 05:11:36.000000', NULL, 1),
(4660001, 670945, 61396, '<td valign="top">Great control of lighting in this minimalistic piece. Good luck.</td>', 'Great control of lighting in this minimalistic piece. Good luck.', '2008-04-26 05:15:20.000000', NULL, 1),
(4660002, 671444, 61396, '<td valign="top">I like the gradient and color</td>', 'I like the gradient and color', '2008-04-26 05:20:11.000000', NULL, 1),
(4660006, 671460, 61396, '<td valign="top">I like how the processing is aligned with the subject</td>', 'I like how the processing is aligned with the subject', '2008-04-26 05:24:27.000000', NULL, 1),
(4660007, 670521, 61396, '<td valign="top">That''s not a grate but a rotated sky scrapper. Good luck.</td>', 'That''s not a grate but a rotated sky scrapper. Good luck.', '2008-04-26 05:28:31.000000', NULL, 1),
(4660015, 671220, 61396, '<td valign="top">Good catch of a tiger!</td>', 'Good catch of a tiger!', '2008-04-26 05:36:47.000000', NULL, 1),
(4660017, 671202, 61396, '<td valign="top">Hopefully not too many will DNMC thinking this is an image of Saturn. Good luck.</td>', 'Hopefully not too many will DNMC thinking this is an image of Saturn. Good luck.', '2008-04-26 05:53:26.000000', NULL, 1),
(4660122, 670706, 91862, '<td valign="top">This shot is incredible.  Very creative! 10!</td>', 'This shot is incredible.  Very creative! 10!', '2008-04-26 09:24:16.000000', NULL, 1),
(4660125, 671304, 91862, '<td valign="top">Very clean shot.  Well done.</td>', 'Very clean shot.  Well done.', '2008-04-26 09:25:34.000000', NULL, 1),
(4660208, 670593, 92900, '<td valign="top">This picture is very nice, It tends to give a very architectural perspective of lookng up the side of a tall skyscraper</td>', 'This picture is very nice, It tends to give a very architectural perspective of lookng up the side of a tall skyscraper', '2008-04-26 11:20:27.000000', NULL, 1),
(4660228, 671339, 55838, '<td valign="top">What an interesting shot.  Educational even!  Like the color tones and the perspective too. 7</td>', 'What an interesting shot.  Educational even!  Like the color tones and the perspective too. 7', '2008-04-26 11:45:01.000000', NULL, 1),
(4660230, 671273, 55838, '<td valign="top">A nice idea and a very pretty delicate feather.  IMO the colors on the background are too harsh (or bold) for the subject.  The feather almost "whispers" with how delicate it is - perhaps a very soft pastel color(s) in the back would help convey that mood throughout.</td>', 'A nice idea and a very pretty delicate feather.  IMO the colors on the background are too harsh (or bold) for the subject.  The feather almost "whispers" with how delicate it is - perhaps a very soft pastel color(s) in the back would help convey that mood throughout.', '2008-04-26 11:50:48.000000', NULL, 1),
