(4662691, 671339, 50695, '<td valign="top">this almost got a posthumous ribbon, but I could not resist the lips. this is one of those shots that I don''t even understand why I like it, or why it has so much emotion. something mysterious brought on by the balanced composition and narrow dof.</td>', 'this almost got a posthumous ribbon, but I could not resist the lips. this is one of those shots that I don''t even understand why I like it, or why it has so much emotion. something mysterious brought on by the balanced composition and narrow dof.', '2008-04-28 11:24:35.000000', NULL, 0),
(4662692, 671285, 23484, '<td valign="top">Great detail and color Catherine. I know what you mean about the sun. I hate photography in the sun.</td>', 'Great detail and color Catherine. I know what you mean about the sun. I hate photography in the sun.', '2008-04-28 11:25:31.000000', NULL, 0),
(4662693, 670507, 23484, '<td valign="top">Nice composition Julianne. I like the colors.</td>', 'Nice composition Julianne. I like the colors.', '2008-04-28 11:26:17.000000', NULL, 0),
